import { useCallback, useEffect, useMemo, useState } from "react";
import { Archive as ArchiveIcon, ArrowLeft, CalendarClock, CalendarDays, CheckCircle2, ChevronDown, ClipboardCheck, Clock3, Copy, Eye, FileText, HeartPulse, Info, ListChecks, MessageSquareText, MoreVertical, Pause, Play, Plus, ShieldAlert, Square, Star, Thermometer, Trash2, UserRound, Users } from "lucide-react";
import PageHeader from "../../../components/layout/PageHeader.jsx";
import Modal from "../../../components/feedback/Modal.jsx";
import SelectField from "../../../components/forms/SelectField.jsx";
import DataTable from "../../../components/tables/DataTable.jsx";
import Badge from "../../../components/ui/Badge.jsx";
import { crewService } from "../../../services/crewService.js";
import { CrewTaskPreview } from "../components/CrewOperationsMobile.jsx";
import CrewTaskBlockRenderer from "../components/CrewTaskBlockRenderer.jsx";
import LocalizedContentEditor from "../components/LocalizedContentEditor.jsx";
import CrewAdminToolbar, { CrewAdminOutletField } from "../components/CrewAdminToolbar.jsx";
import { useCrewAdminOutlet } from "../context/CrewAdminOutletContext.jsx";
import { detectContentLanguage, localizationLanguageSummary, taskLocalizationUnits } from "../utils/localizedContent.js";

const localDate = (value = new Date()) => `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, "0")}-${String(value.getDate()).padStart(2, "0")}`;
const TASK_TYPES = [{ value: "checklist", label: "Checklist" }, { value: "instruction", label: "Instruction / Text" }, { value: "health_check", label: "Health Check" }, { value: "confirmation", label: "Confirmation" }, { value: "sop_review", label: "SOP Review" }];
const BLOCK_TYPES = [{ value: "text", label: "Text / Instruction" }, { value: "checklist_item", label: "Checklist Item" }, { value: "key_point", label: "Key Point" }, { value: "image", label: "Image · Secure media required", disabled: true }, { value: "sop_reference", label: "SOP Reference" }, { value: "yes_no", label: "Yes / No" }, { value: "single_choice", label: "Single Choice" }, { value: "number", label: "Number Input" }, { value: "temperature", label: "Temperature Input" }, { value: "short_text", label: "Short Text" }, { value: "health_rating", label: "Health Rating" }, { value: "confirmation", label: "Confirmation" }];
const POSITIONS = ["Service Crew", "Kitchen Crew", "Cashier", "Part Time Crew", "Supervisor", "Outlet Manager"];
const statusLabel = (value) => ({ not_started: "Not Started", in_progress: "In Progress", completed: "Completed", completed_with_exceptions: "Completed · Exceptions", exception: "Exception", overdue: "Overdue", review_required: "Review Required", active: "Active", paused: "Paused", ended: "Ended", archived: "Archived", draft: "Draft", past: "Past date", none: "No upcoming run" }[value] || value);
const tone = (value) => ["completed", "active"].includes(value) ? "success" : ["overdue", "critical", "completed_with_exceptions", "exception"].includes(value) ? "danger" : ["in_progress", "important", "review_required", "draft", "paused"].includes(value) ? "warning" : "neutral";
const blankBlock = (type = "checklist_item") => ({ id: `temp:${crypto.randomUUID()}`, block_type: type, title: "", description: "", is_required: !["text", "key_point", "sop_reference"].includes(type), evidence_requirement: "none", sop_version_id: "", config: { localization_key: crypto.randomUUID() } });
const blankTask = (date) => ({ _mode: "create", name: "", task_type: "checklist", schedule_type: "one_time", effective_date: date, schedule_end_date: "", start_time: "", due_time: "", schedule_config: { frequency: "every_day", weekdays: [] }, assignment_type: "all_crew", applicable_positions: [], applicable_employee_ids: [], applicable_group_names: [], on_duty_only: false, priority: "normal", completion_rule: "one_for_team", allow_exception: true, exception_requires_reason: true, manager_review_required: false, allow_late_completion: true, blocks: [blankBlock()] });
const RESPONSE_BLOCK_TYPES = new Set(["checklist_item", "yes_no", "single_choice", "number", "temperature", "short_text", "health_rating", "confirmation"]);
const canonicalCompletionRule = (value) => value === "any_assigned" ? "one_for_team" : value;
const builderCompletionRuleLabel = (value) => canonicalCompletionRule(value) === "every_assigned" ? "Each assigned Crew must complete" : "One completion for this task";
const additionalNoteRule = (blocks) => blocks.some((block) => block.evidence_requirement === "note") ? "note" : blocks.some((block) => block.evidence_requirement === "optional_note") ? "optional_note" : "none";

export default function CrewOperationsAdminPage({ auth, ui, store }) {
  const { outlets, outletId, setOutletId } = useCrewAdminOutlet(store?.outlets || []); const [from, setFrom] = useState(localDate()); const [to, setTo] = useState(localDate());
  const [status, setStatus] = useState("active"); const [assignee, setAssignee] = useState("all"); const [data, setData] = useState({ definitions: [], instances: [], published_sops: [], employees: [], review_queue: [] });
  const [loading, setLoading] = useState(true); const [editor, setEditor] = useState(null); const [detail, setDetail] = useState(null); const [scheduleTask, setScheduleTask] = useState(null); const [actionMenu, setActionMenu] = useState(null);
  const canManage = auth.hasPermission("crew_operations.manage");
  const canReview = auth.hasPermission("crew_operations.review");
  async function refresh() { if (!outletId) return; setLoading(true); try { setData(await crewService.tasksAdminData(outletId, from, to)); } catch (cause) { ui.notify({ title: "Unable to load Tasks", message: cause.message, tone: "error" }); } finally { setLoading(false); } }
  useEffect(() => { refresh(); }, [outletId, from, to]);
  async function save(task) { try { const versionId = await crewService.saveTask(outletId, task); const detail = await crewService.taskAdminDetail(versionId); const canonical = detail?.draft || detail?.definition || { ...task, id: versionId }; await crewService.saveLocalizedContentUnits("task", versionId, taskLocalizationUnits(canonical, task._source_language || detectContentLanguage(task.name))); setEditor(null); await refresh(); ui.notify({ title: "Task draft saved", message: "Schedule, assignment, content and language source were saved together." }); return versionId; } catch (cause) { ui.notify({ title: "Unable to save Task", message: cause.message, tone: "error" }); return null; } }
  async function publish(row) {
    try {
      const localization = await crewService.localizedContentAdmin("task", row.id);
      const confirmed = await ui.confirm({
        title: "Activate this Task version?",
        message: `${localizationLanguageSummary(localization)}. Future instances will freeze this Task and its current language content.`,
        confirmLabel: "Activate Task",
        tone: "success",
      });
      if (!confirmed) return false;
      await crewService.activateOperationTemplate(row.id);
      await refresh();
      ui.notify({ title: "Task activated", message: "Future instances now use this immutable revision." });
      return true;
    } catch (cause) { ui.notify({ title: "Unable to activate Task", message: cause.message, tone: "error" }); return false; }
  }
  async function duplicate(row) { try { await crewService.duplicateTask(row.id); await refresh(); ui.notify({ title: "Task duplicated", message: "A separate Draft copy is ready to edit." }); } catch (cause) { ui.notify({ title: "Unable to duplicate Task", message: cause.message, tone: "error" }); } }
  async function openDraft(row) {
    try {
      const ensured = await crewService.ensureTaskDraft(row.draft_version?.id || row.id);
      const taskDetail = await crewService.taskAdminDetail(ensured.id);
      const draft = taskDetail?.draft;
      if (!draft) throw new Error("The Task Draft could not be loaded.");
      setEditor(toEditor({ ...draft, _mode: row.has_draft || ensured.created === false ? "draft" : "revision", _source_revision: row.current_version?.revision || row.revision }));
    } catch (cause) { ui.notify({ title: "Unable to open Task Draft", message: cause.message, tone: "error" }); }
  }
  async function approveReview(row) { try { await crewService.reviewTask(row.instance_id, row.employee_id, "approved"); await refresh(); ui.notify({ title: "Task review approved", message: `${row.employee_name}'s completion is finalized.` }); } catch (cause) { ui.notify({ title: "Unable to review Task", message: cause.message, tone: "error" }); } }
  async function manageSchedule(row, action, endDate = null) {
    const labels = { pause: "Pause Task schedule?", resume: "Resume Task schedule?", end: "End Task schedule permanently?", archive: "Archive ended Task?" };
    if (labels[action] && !await ui.confirm({ title: labels[action], message: action === "end" || action === "archive" ? "Historical instances, results and frozen evidence will remain available." : "Future instance generation will follow the updated lifecycle state.", confirmLabel: action === "end" ? "End Schedule" : statusLabel(action === "pause" ? "paused" : action === "resume" ? "active" : action === "archive" ? "archived" : action) })) return;
    try {
      await crewService.manageTaskSchedule(row.id, action, endDate);
      setScheduleTask(null); setActionMenu(null); await refresh();
      ui.notify({ title: "Task schedule updated", message: "Historical execution results were preserved." });
    } catch (cause) { ui.notify({ title: "Unable to update Task schedule", message: cause.message, tone: "error" }); }
  }
  const rows = useMemo(() => data.definitions.filter((row) => status === "all" || row.status === status).filter((row) => assignee === "all" || row.assignment_type === assignee), [data.definitions, status, assignee]);
  const counts = { active: data.definitions.filter((x) => x.status === "active").length, paused: data.definitions.filter((x) => x.status === "paused").length, ended: data.definitions.filter((x) => x.status === "ended").length, draft: data.definitions.filter((x) => x.status === "draft").length };
  return <div className="crew-operations-page space-y-4"><PageHeader section="Crew · Operations" title="Tasks" description="Plan, assign and review every outlet task from one place." />
    <CrewAdminToolbar outlet={<CrewAdminOutletField />} time={<div className="flex gap-2"><label className="field-label">From<input className="control mt-1 w-full" type="date" value={from} onChange={(event) => setFrom(event.target.value)} /></label><label className="field-label">To<input className="control mt-1 w-full" type="date" value={to} onChange={(event) => setTo(event.target.value)} /></label></div>} filters={<><SelectField label="Status" ariaLabel="Status" value={status} onChange={setStatus} options={[{ value: "all", label: "All" }, { value: "draft", label: "Draft" }, { value: "active", label: "Active" }, { value: "paused", label: "Paused" }, { value: "ended", label: "Ended" }, { value: "archived", label: "Archived" }]} /><SelectField label="Assignment" ariaLabel="Assignee" value={assignee} onChange={setAssignee} options={[{ value: "all", label: "All" }, { value: "all_crew", label: "All Crew" }, { value: "position", label: "Position" }, { value: "specific_crew", label: "Specific Crew" }, { value: "group", label: "Group" }]} /></>} primary={canManage ? <button className="btn-primary" onClick={() => setEditor(blankTask(from))}><Plus size={16} /> Create Task</button> : null} />
    <section className="grid gap-3 md:grid-cols-4"><Metric icon={Play} label="Active" value={counts.active} /><Metric icon={Pause} label="Paused" value={counts.paused} /><Metric icon={Square} label="Ended" value={counts.ended} /><Metric icon={FileText} label="Draft" value={counts.draft} /></section>
    <section className="card overflow-hidden">{loading ? <div className="p-8 text-sm text-text-muted">Loading Tasks…</div> : <DataTable rows={rows} getRowKey={(row) => row.id} columns={[
      { key: "task", header: "Task", render: (row) => <span className="flex flex-col"><strong>{row.name}</strong><small className="text-text-muted">{TASK_TYPES.find((x) => x.value === row.task_type)?.label || "Checklist"} · {row.blocks?.length || 0} blocks</small></span> },
      { key: "schedule", header: "Schedule", render: scheduleLabel },
      { key: "assignment", header: "Assignment", render: assignmentLabel },
      { key: "priority", header: "Priority", render: (row) => <Badge tone={tone(row.priority)}>{priorityLabel(row.priority)}</Badge> },
      { key: "version", header: "Version", render: (row) => <TaskVersionCell row={row} /> },
      { key: "status", header: "Status", render: (row) => <Badge tone={tone(row.status)}>{statusLabel(row.status)}</Badge> },
      { key: "next", header: "Next Run", render: (row) => <TaskDateTime value={row.next_run} /> },
      { key: "actions", header: "Actions", align: "right", className: "whitespace-nowrap", render: (row) => <span className="inline-flex items-center justify-end gap-1.5"><button className="icon-btn h-9 w-9 min-h-9" aria-label={`View ${row.name}`} title="View" onClick={() => setDetail(row)}><Eye size={16} /></button>{canManage ? <button className="btn-secondary min-h-9 px-3 py-1.5 text-xs font-semibold" onClick={() => openDraft(row)}>{row.has_draft || row.status === "draft" ? "Continue Draft" : "New Revision"}</button> : null}{canManage ? <button className="icon-btn h-9 w-9 min-h-9" aria-label={`More actions for ${row.name}`} onClick={(event) => { const rect = event.currentTarget.getBoundingClientRect(); setActionMenu(actionMenu?.id === row.id ? null : { id: row.id, row, top: rect.bottom + 6, right: Math.max(12, window.innerWidth - rect.right) }); }}><MoreVertical size={16} /></button> : null}</span> }
    ]} density="compact" tableClassName="min-w-[1020px]" />}</section>
    {data.review_queue?.length ? <section className="card overflow-hidden"><div className="border-b border-border px-5 py-4"><h2 className="font-bold">Manager Review</h2><p className="text-sm text-text-secondary">Completions that require outlet review before finalization.</p></div><DataTable rows={data.review_queue} getRowKey={(row) => `${row.instance_id}:${row.employee_id}`} columns={[{ key: "task", header: "Task", render: (row) => row.task_name }, { key: "employee", header: "Crew", render: (row) => row.employee_name }, { key: "date", header: "Date", render: (row) => row.business_date }, { key: "status", header: "Status", render: () => <Badge tone="warning">Review Required</Badge> }, { key: "action", header: "Action", align: "right", render: (row) => canReview ? <button className="btn-secondary px-3 py-1.5 text-xs" onClick={() => approveReview(row)}>Approve</button> : null }]} /></section> : null}
    {editor ? <TaskEditor initial={editor} employees={data.employees} sops={data.published_sops} outletName={outlets.find((row) => row.id === outletId)?.name || "Selected outlet"} onConfirm={ui.confirm} onClose={() => setEditor(null)} onSave={save} onPublish={publish} /> : null}
    {detail ? <TaskDetail task={detail} canManage={canManage} onEditDraft={openDraft} onClose={() => setDetail(null)} /> : null}
    {scheduleTask ? <ManageSchedule task={scheduleTask} onClose={() => setScheduleTask(null)} onAction={(action, endDate) => manageSchedule(scheduleTask, action, endDate)} /> : null}
    {actionMenu ? <TaskActionMenu row={actionMenu.row} position={actionMenu} onManage={() => { setScheduleTask(actionMenu.row); setActionMenu(null); }} onDuplicate={() => duplicate(actionMenu.row)} onArchive={() => manageSchedule(actionMenu.row, "archive")} /> : null}
  </div>;
}

function TaskEditor({ initial, employees, sops, outletName, onConfirm, onClose, onSave, onPublish }) {
  const [draft, setDraft] = useState(initial);
  const initialSourceLanguage = useMemo(() => initial._source_language || detectContentLanguage(initial.name || initial.blocks?.map((block) => `${block.title} ${block.description || ""}`).join(" ")), [initial]);
  const [sourceLanguage, setSourceLanguage] = useState(initialSourceLanguage);
  const [savedSourceLanguage, setSavedSourceLanguage] = useState(initialSourceLanguage);
  const hydrateSourceLanguage = useCallback((next) => { setSourceLanguage(next); setSavedSourceLanguage(next); }, []);
  const [saving, setSaving] = useState(false);
  const [previewing, setPreviewing] = useState(false);
  const initialSignature = useMemo(() => JSON.stringify(initial), [initial]);
  const dirty = JSON.stringify(draft) !== initialSignature || sourceLanguage !== savedSourceLanguage;
  const valid = Boolean(draft.name.trim() && draft.blocks.length && draft.effective_date);
  const structuredCount = draft.blocks.filter((block) => RESPONSE_BLOCK_TYPES.has(block.block_type)).length;
  const previewTask = { ...draft, blocks: draft.blocks.map((block) => withSopPreview(block, sops)) };
  const title = draft._mode === "revision" ? `Create New Revision · ${draft.name}` : draft.id ? `Continue Draft · ${draft.name}` : "Create Task";
  const description = draft._mode === "revision" ? `Current Active Version v${draft._source_revision || "current"} · Creating Draft v${Number(draft._source_revision || 0) + 1}. Existing task instances remain frozen on their original versions.` : "Set up who receives this task, when it appears and what Crew must complete.";
  const updateBlock = (index, patch) => setDraft((value) => ({ ...value, blocks: value.blocks.map((block, i) => i === index ? { ...block, ...patch } : block) }));
  async function requestClose() {
    if (!dirty) return onClose();
    const discard = onConfirm ? await onConfirm({ title: "You have unsaved changes.", message: "Discard this Task draft or continue editing?", confirmLabel: "Discard", cancelLabel: "Continue Editing", tone: "danger" }) : false;
    if (discard) onClose();
  }
  async function saveDraft() { setSaving(true); try { await onSave({ ...draft, _source_language: sourceLanguage }); } finally { setSaving(false); } }
  async function activate() { setSaving(true); try { if (await onPublish({ ...draft, _source_language: sourceLanguage })) onClose(); } finally { setSaving(false); } }
  return <><Modal title={title} description={description} headerActions={<Badge tone={dirty ? "warning" : "success"}>{dirty ? "Unsaved changes" : "Saved"}</Badge>} size="3xl" panelClassName="max-h-[92vh]" bodyClassName="p-0" footerClassName="justify-between" onClose={requestClose} footer={<><button type="button" className="btn-secondary" onClick={() => setPreviewing(true)}><Eye size={16} /> Preview as Crew</button><span className="flex items-center gap-2"><button type="button" className="btn-secondary" onClick={requestClose}>Cancel</button><button type="button" className="btn-primary" disabled={saving || !valid} onClick={saveDraft}>{saving ? "Saving…" : "Save Draft"}</button>{draft.id && draft.status === "draft" ? <button type="button" className="btn-primary" disabled={saving || !valid || dirty} title={dirty ? "Save draft changes before activation" : undefined} onClick={activate}>Activate Task</button> : null}</span></>}><div className="grid items-start xl:grid-cols-[minmax(0,1fr)_260px]"><main className="space-y-5 p-5 md:p-6"><TaskSection title="Basic information" description="Name the task and choose the closest starting format."><BasicEditor draft={draft} setDraft={setDraft} /></TaskSection><TaskSection title="Schedule" description="Choose when this task should appear for Crew."><ScheduleEditor draft={draft} setDraft={setDraft} /></TaskSection><TaskSection title="Assignment" description="Choose which Crew should receive this task."><AssignmentEditor draft={draft} setDraft={setDraft} employees={employees} outletName={outletName} /></TaskSection><TaskSection title="Task content" description="Build what Crew needs to read, check or submit." action={null}><ContentEditor draft={draft} setDraft={setDraft} updateBlock={updateBlock} sops={sops} /></TaskSection><TaskSection title="Completion" description="Define who completes the task and what evidence is required."><RulesEditor draft={draft} setDraft={setDraft} structuredCount={structuredCount} /></TaskSection><LocalizedContentEditor domain="task" versionId={draft.id} sourceLanguage={sourceLanguage} onSourceLanguageChange={setSourceLanguage} onHydrateSourceLanguage={hydrateSourceLanguage} sourceUnits={taskLocalizationUnits(draft, sourceLanguage)} sourceDirty={dirty} confirm={onConfirm} disabled={draft.status && draft.status !== "draft"} /></main><TaskSummary draft={draft} outletName={outletName} structuredCount={structuredCount} /></div></Modal>{previewing ? <Modal title={draft.name || "Untitled Task"} description="Crew preview · Unsaved changes are included" size="md" panelClassName="max-h-[90vh]" onClose={() => setPreviewing(false)} footer={<button className="btn-secondary" onClick={() => setPreviewing(false)}>Back to Editor</button>}><CrewTaskPreview task={previewTask} onBack={() => setPreviewing(false)} /></Modal> : null}</>;
}

function TaskSection({ title, description, children }) { return <section className="rounded-2xl bg-slate-50/80 p-4 md:p-5"><header className="mb-4"><h3 className="text-base font-bold text-text-primary">{title}</h3><p className="mt-1 text-sm text-text-secondary">{description}</p></header>{children}</section>; }

const TYPE_CHOICES = [
  { value: "checklist", label: "Checklist", icon: ClipboardCheck }, { value: "instruction", label: "Instruction", icon: FileText }, { value: "health_check", label: "Health Check", icon: HeartPulse }, { value: "confirmation", label: "Confirmation", icon: CheckCircle2 }, { value: "sop_review", label: "SOP Review", icon: ListChecks },
];
function typeDefaultBlock(type) { return blankBlock({ instruction: "text", health_check: "health_rating", confirmation: "confirmation", sop_review: "sop_reference" }[type] || "checklist_item"); }
function BasicEditor({ draft, setDraft }) {
  function chooseType(task_type) { const pristine = draft.blocks.length === 1 && !draft.blocks[0].title && !draft.blocks[0].description; setDraft({ ...draft, task_type, blocks: pristine ? [typeDefaultBlock(task_type)] : draft.blocks }); }
  return <div className="space-y-4"><label className="field-label">Task Name *<input className="control mt-1 w-full" value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} placeholder="e.g. Opening Checklist" /></label><fieldset><legend className="field-label mb-2">Task Type *</legend><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-5">{TYPE_CHOICES.map(({ value, label, icon: Icon }) => <button key={value} type="button" aria-pressed={draft.task_type === value} className={`flex min-h-20 flex-col items-start justify-between rounded-xl border p-3 text-left transition-colors ${draft.task_type === value ? "border-primary bg-emerald-50 text-primary" : "border-border bg-white text-text-primary hover:border-emerald-300"}`} onClick={() => chooseType(value)}><Icon size={18} /><span className="text-sm font-semibold">{label}</span></button>)}</div></fieldset><fieldset><legend className="field-label mb-2">Priority</legend><div className="inline-flex rounded-xl bg-slate-200/70 p-1">{[["normal", "Normal"], ["important", "Important"], ["critical", "Critical"]].map(([value, label]) => <button key={value} type="button" aria-pressed={draft.priority === value} className={`rounded-lg px-4 py-2 text-sm font-semibold ${draft.priority === value ? value === "critical" ? "bg-rose-600 text-white" : value === "important" ? "bg-amber-500 text-white" : "bg-white text-text-primary shadow-sm" : "text-text-secondary"}`} onClick={() => setDraft({ ...draft, priority: value })}>{label}</button>)}</div></fieldset></div>;
}

function ScheduleEditor({ draft, setDraft }) {
  const frequency = draft.schedule_config?.frequency || "every_day";
  const setSchedule = (patch) => setDraft({ ...draft, schedule_config: { ...draft.schedule_config, ...patch } });
  const choices = [["one_time", "One-time", "A task on one selected date"], ["recurring", "Recurring", "Repeat on a predictable schedule"], ["shift_based", "Shift-based", "Follow each Crew member’s shift"]];
  return <div className="space-y-4"><div className="grid gap-2 md:grid-cols-3">{choices.map(([value, label, help]) => <button key={value} type="button" aria-pressed={draft.schedule_type === value} className={`rounded-xl border p-3 text-left ${draft.schedule_type === value ? "border-primary bg-emerald-50" : "border-border bg-white"}`} onClick={() => setDraft({ ...draft, schedule_type: value, schedule_end_date: value === "one_time" ? "" : draft.schedule_end_date, on_duty_only: value === "shift_based" ? true : draft.on_duty_only })}><span className="flex items-center gap-2 text-sm font-bold"><i className={`h-3 w-3 rounded-full border-2 ${draft.schedule_type === value ? "border-primary bg-primary ring-2 ring-emerald-100" : "border-slate-400"}`} />{label}</span><small className="mt-1 block pl-5 text-text-secondary">{help}</small></button>)}</div><div className="grid gap-4 md:grid-cols-2"><label className="field-label">{draft.schedule_type === "one_time" ? "Task Date" : "Starts"}<input className="control mt-1 w-full" type="date" value={draft.effective_date} onChange={(event) => setDraft({ ...draft, effective_date: event.target.value })} /></label>{draft.schedule_type !== "one_time" ? <label className="field-label">End Date <span className="font-normal text-text-muted">(optional)</span><input className="control mt-1 w-full" type="date" min={draft.effective_date} value={draft.schedule_end_date || ""} onChange={(event) => setDraft({ ...draft, schedule_end_date: event.target.value })} /><small className="mt-1 block font-normal text-text-secondary">Leave blank for no end date.</small></label> : null}{draft.schedule_type === "recurring" ? <SelectField label="Repeats" value={frequency} onChange={(value) => setSchedule({ frequency: value })} options={[{ value: "every_day", label: "Every day" }, { value: "specific_weekdays", label: "Specific weekdays" }, { value: "weekly", label: "Weekly" }, { value: "monthly", label: "Monthly" }, { value: "custom_interval", label: "Custom interval" }]} /> : null}{draft.schedule_type === "recurring" && frequency === "specific_weekdays" ? <fieldset className="md:col-span-2"><legend className="field-label mb-2">Days</legend><div className="flex flex-wrap gap-2">{[[1, "M"], [2, "T"], [3, "W"], [4, "T"], [5, "F"], [6, "S"], [7, "S"]].map(([day, label]) => { const active = (draft.schedule_config?.weekdays || []).includes(day); return <button key={day} type="button" aria-label={["", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"][day]} aria-pressed={active} className={`h-10 w-10 rounded-full text-sm font-bold ${active ? "bg-primary text-white" : "border border-border bg-white text-text-secondary"}`} onClick={() => setSchedule({ weekdays: active ? (draft.schedule_config?.weekdays || []).filter((value) => value !== day) : [...(draft.schedule_config?.weekdays || []), day].sort() })}>{label}</button>; })}</div></fieldset> : null}{draft.schedule_type === "recurring" && frequency === "weekly" ? <SelectField label="Weekday" value={draft.schedule_config?.weekday || 1} onChange={(weekday) => setSchedule({ weekday: Number(weekday) })} options={[[1, "Monday"], [2, "Tuesday"], [3, "Wednesday"], [4, "Thursday"], [5, "Friday"], [6, "Saturday"], [7, "Sunday"]].map(([value, label]) => ({ value, label }))} /> : null}{draft.schedule_type === "recurring" && frequency === "monthly" ? <label className="field-label">Day of month<input className="control mt-1 w-full" type="number" min="1" max="31" value={draft.schedule_config?.day || 1} onChange={(event) => setSchedule({ day: Number(event.target.value) })} /></label> : null}{draft.schedule_type === "recurring" && frequency === "custom_interval" ? <label className="field-label">Repeat every (days)<input className="control mt-1 w-full" type="number" min="1" max="365" value={draft.schedule_config?.interval_days || 1} onChange={(event) => setSchedule({ interval_days: Number(event.target.value) })} /></label> : null}{draft.schedule_type === "shift_based" ? <SelectField label="Trigger" value={draft.schedule_config?.shift_phase || "during_shift"} onChange={(shift_phase) => setSchedule({ shift_phase })} options={[{ value: "before_shift", label: "Before shift" }, { value: "start_of_shift", label: "Start of shift" }, { value: "during_shift", label: "During shift" }, { value: "end_of_shift", label: "End of shift" }]} /> : null}<label className="field-label">Start time<input className="control mt-1 w-full" type="time" value={draft.start_time || ""} onChange={(event) => setDraft({ ...draft, start_time: event.target.value })} /></label><label className="field-label">Due time<input className="control mt-1 w-full" type="time" value={draft.due_time || ""} onChange={(event) => setDraft({ ...draft, due_time: event.target.value })} /></label></div></div>;
}

function AssignmentEditor({ draft, setDraft, employees, outletName }) {
  const [query, setQuery] = useState("");
  const choices = [["all_crew", "All Crew", Users], ["position", "Position", UserRound], ["specific_crew", "Specific Crew", UserRound], ["group", "Group", Users]];
  const visibleEmployees = employees.filter((employee) => `${employee.name} ${employee.position}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="space-y-4"><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">{choices.map(([value, label, Icon]) => <button key={value} type="button" aria-pressed={draft.assignment_type === value} className={`flex items-center gap-3 rounded-xl border p-3 text-left text-sm font-semibold ${draft.assignment_type === value ? "border-primary bg-emerald-50 text-primary" : "border-border bg-white"}`} onClick={() => setDraft({ ...draft, assignment_type: value })}><Icon size={17} /><span>{label}</span></button>)}</div>{draft.assignment_type === "position" ? <fieldset><legend className="field-label mb-2">Positions</legend><div className="flex flex-wrap gap-2">{POSITIONS.map((position) => { const active = draft.applicable_positions.includes(position); return <button key={position} type="button" aria-pressed={active} className={active ? "btn-primary" : "btn-secondary"} onClick={() => setDraft({ ...draft, applicable_positions: active ? draft.applicable_positions.filter((x) => x !== position) : [...draft.applicable_positions, position] })}>{position}</button>; })}</div></fieldset> : null}{draft.assignment_type === "specific_crew" ? <fieldset><legend className="field-label mb-2">Crew</legend><input className="control mb-3 w-full" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search employee or position" /> <div className="grid max-h-44 gap-2 overflow-y-auto sm:grid-cols-2">{visibleEmployees.map((employee) => <label key={employee.id} className="flex items-center gap-2 rounded-lg border border-border bg-white p-2 text-sm"><input type="checkbox" checked={draft.applicable_employee_ids.includes(employee.id)} onChange={(event) => setDraft({ ...draft, applicable_employee_ids: event.target.checked ? [...draft.applicable_employee_ids, employee.id] : draft.applicable_employee_ids.filter((x) => x !== employee.id) })} /><span><b className="block">{employee.name}</b><small className="text-text-secondary">{employee.position}</small></span></label>)}</div></fieldset> : null}{draft.assignment_type === "group" ? <label className="field-label">Group names<input className="control mt-1 w-full" value={draft.applicable_group_names.join(", ")} onChange={(event) => setDraft({ ...draft, applicable_group_names: event.target.value.split(",").map((x) => x.trim()).filter(Boolean) })} placeholder="e.g. Floor Team, Kitchen Team" /></label> : null}<label className="flex items-center gap-2 rounded-xl bg-white p-3 text-sm font-medium"><input type="checkbox" checked={draft.on_duty_only} onChange={(event) => setDraft({ ...draft, on_duty_only: event.target.checked })} />Only Crew scheduled to work that day</label><div className="flex items-start gap-3 rounded-xl bg-emerald-50 p-3 text-sm text-emerald-900"><Info className="mt-0.5 shrink-0" size={16} /><span><b className="block">Assigned to</b>{assignmentSummary(draft, outletName)}</span></div></div>;
}

const BLOCK_GROUPS = [
  { label: "Action", items: ["checklist_item", "confirmation", "yes_no"] },
  { label: "Information", items: ["text", "key_point", "sop_reference"] },
  { label: "Input", items: ["short_text", "number", "temperature", "single_choice", "health_rating", "image"] },
];
const BLOCK_ICONS = { checklist_item: ClipboardCheck, confirmation: CheckCircle2, yes_no: CheckCircle2, text: FileText, key_point: Star, sop_reference: ListChecks, short_text: MessageSquareText, number: ListChecks, temperature: Thermometer, single_choice: ListChecks, health_rating: HeartPulse, image: Eye };
function ContentEditor({ draft, setDraft, updateBlock, sops }) {
  const [expandedId, setExpandedId] = useState(draft.blocks[0]?.id || null);
  const [pickerOpen, setPickerOpen] = useState(false);
  const [menuId, setMenuId] = useState(null);
  const move = (index, offset) => { const blocks = [...draft.blocks]; const [block] = blocks.splice(index, 1); blocks.splice(index + offset, 0, block); setDraft({ ...draft, blocks }); setMenuId(null); };
  const add = (type) => { const block = blankBlock(type); setDraft({ ...draft, blocks: [...draft.blocks, block] }); setExpandedId(block.id); setPickerOpen(false); };
  const duplicateBlock = (index) => { const copy = { ...draft.blocks[index], id: `temp:${crypto.randomUUID()}`, config: { ...draft.blocks[index].config } }; const blocks = [...draft.blocks]; blocks.splice(index + 1, 0, copy); setDraft({ ...draft, blocks }); setExpandedId(copy.id); setMenuId(null); };
  return <div className="space-y-3"><div className="flex items-center justify-between gap-3"><p className="text-xs text-text-secondary">{draft.blocks.length} block{draft.blocks.length === 1 ? "" : "s"} · order freezes into each daily instance</p><button type="button" className="btn-secondary" onClick={() => setPickerOpen(true)}><Plus size={15} /> Add Block</button></div>{draft.blocks.length ? draft.blocks.map((block, index) => { const expanded = expandedId === block.id; const Icon = BLOCK_ICONS[block.block_type] || ListChecks; return <article key={block.id || index} className={`rounded-xl border bg-white ${expanded ? "border-emerald-300" : "border-border"}`}><div className="flex items-center gap-3 p-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-emerald-50 text-primary"><Icon size={17} /></span><button type="button" className="min-w-0 flex-1 text-left" onClick={() => setExpandedId(expanded ? null : block.id)}><span className="flex items-center gap-2"><b className="text-xs text-text-muted">{String(index + 1).padStart(2, "0")}</b><strong className="truncate text-sm">{block.title || BLOCK_TYPES.find((item) => item.value === block.block_type)?.label}</strong></span><small className="mt-0.5 block truncate text-text-secondary">{block.is_required !== false ? "Required" : "Optional"}{block.description ? ` · ${block.description}` : ""}</small></button><button type="button" className="icon-btn" aria-label={`More actions for block ${index + 1}`} onClick={() => setMenuId(menuId === block.id ? null : block.id)}><MoreVertical size={16} /></button><button type="button" className="icon-btn" aria-label={`${expanded ? "Collapse" : "Expand"} block ${index + 1}`} onClick={() => setExpandedId(expanded ? null : block.id)}><ChevronDown className={expanded ? "rotate-180" : ""} size={16} /></button></div>{menuId === block.id ? <div className="flex flex-wrap justify-end gap-2 border-t border-border bg-slate-50 px-3 py-2"><button type="button" className="btn-secondary px-3 py-1.5 text-xs" disabled={!index} onClick={() => move(index, -1)}>Move up</button><button type="button" className="btn-secondary px-3 py-1.5 text-xs" disabled={index === draft.blocks.length - 1} onClick={() => move(index, 1)}>Move down</button><button type="button" className="btn-secondary px-3 py-1.5 text-xs" onClick={() => duplicateBlock(index)}><Copy size={13} /> Duplicate</button><button type="button" className="btn-secondary px-3 py-1.5 text-xs text-rose-700" onClick={() => { setDraft({ ...draft, blocks: draft.blocks.filter((_, i) => i !== index) }); setMenuId(null); }}><Trash2 size={13} /> Delete</button></div> : null}{expanded ? <BlockEditor block={block} index={index} updateBlock={updateBlock} sops={sops} /> : null}</article>; }) : <div className="rounded-xl border border-dashed border-slate-300 bg-white p-8 text-center"><ClipboardCheck className="mx-auto text-text-muted" size={24} /><p className="mt-2 font-semibold">No content blocks yet</p><p className="text-sm text-text-secondary">Add an instruction, checklist item or response field.</p></div>}{pickerOpen ? <BlockPicker onClose={() => setPickerOpen(false)} onSelect={add} /> : null}</div>;
}
function BlockPicker({ onClose, onSelect }) {
  return <div className="fixed inset-0 z-toast-layer flex items-center justify-center bg-slate-950/30 p-4" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section role="dialog" aria-modal="true" aria-label="Add content block" className="w-full max-w-lg rounded-2xl bg-white p-5 shadow-card"><div className="mb-4 flex items-start justify-between"><div><h3 className="font-bold">Add content block</h3><p className="text-sm text-text-secondary">Choose what Crew should read or complete.</p></div><button type="button" className="icon-btn" aria-label="Close block selector" onClick={onClose}>×</button></div><div className="space-y-4">{BLOCK_GROUPS.map((group) => <fieldset key={group.label}><legend className="mb-2 text-sm font-bold">{group.label}</legend><div className="grid gap-2 sm:grid-cols-2">{group.items.map((type) => { const item = BLOCK_TYPES.find((option) => option.value === type); const Icon = BLOCK_ICONS[type] || ListChecks; return <button key={type} type="button" disabled={item.disabled} className="flex items-center gap-3 rounded-xl border border-border p-3 text-left text-sm font-semibold hover:border-emerald-300 disabled:cursor-not-allowed disabled:bg-slate-50 disabled:text-text-muted" onClick={() => onSelect(type)}><Icon size={17} /><span>{item.label}{item.disabled ? <small className="block font-normal">Media storage required</small> : null}</span></button>; })}</div></fieldset>)}</div></section></div>;
}

function BlockEditor({ block, index, updateBlock, sops }) {
  const previewBlock = withSopPreview(block, sops);
  return <div className="grid gap-3 border-t border-border bg-slate-50/60 p-4 md:grid-cols-2">
    <SelectField label="Block Type" value={block.block_type} onChange={(block_type) => updateBlock(index, { block_type, is_required: !["text", "key_point", "sop_reference"].includes(block_type) })} options={BLOCK_TYPES} />
    <label className="field-label">Title<input className="control mt-1 w-full" value={block.title} onChange={(event) => updateBlock(index, { title: event.target.value })} /></label>
    <label className="field-label md:col-span-2">Content / instruction<textarea className="control mt-1 min-h-20 w-full py-2" value={block.description || ""} onChange={(event) => updateBlock(index, { description: event.target.value })} /></label>
    {block.block_type === "sop_reference" ? <SelectField label="Published SOP · exact version" value={block.sop_version_id || ""} onChange={(sop_version_id) => updateBlock(index, { sop_version_id })} options={[{ value: "", label: "Select SOP" }, ...sops.map((sop) => ({ value: sop.version_id, label: `${sop.title} · v${sop.version}` }))]} /> : null}
    {block.block_type === "single_choice" ? <><label className="field-label">Options<input className="control mt-1 w-full" value={(block.config?.options || []).join(", ")} onChange={(event) => updateBlock(index, { config: { ...block.config, options: event.target.value.split(",").map((x) => x.trim()).filter(Boolean) } })} placeholder="Yes, No, Not applicable" /></label><label className="field-label">Expected value (optional)<input className="control mt-1 w-full" value={block.config?.expected_value || ""} onChange={(event) => updateBlock(index, { config: { ...block.config, expected_value: event.target.value } })} /></label></> : null}
    {["number", "temperature"].includes(block.block_type) ? <><label className="field-label">Minimum<input className="control mt-1 w-full" type="number" value={block.config?.min ?? ""} onChange={(event) => updateBlock(index, { config: { ...block.config, min: event.target.value } })} /></label><label className="field-label">Maximum<input className="control mt-1 w-full" type="number" value={block.config?.max ?? ""} onChange={(event) => updateBlock(index, { config: { ...block.config, max: event.target.value } })} /></label><label className="field-label">Unit<input className="control mt-1 w-full" value={block.config?.unit || (block.block_type === "temperature" ? "°C" : "")} onChange={(event) => updateBlock(index, { config: { ...block.config, unit: event.target.value } })} /></label></> : null}
    {block.block_type === "health_rating" ? <div className="rounded-lg bg-emerald-50 p-3 text-sm text-emerald-900"><b>Health rating responses</b><p>Good · Needs Attention · Not Checked. Needs Attention requires a note.</p></div> : null}
    <label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={block.is_required !== false} onChange={(event) => updateBlock(index, { is_required: event.target.checked })} />Required</label>
    <details className="crew-task-inline-preview" open>
      <summary>Mobile Preview</summary>
      <div><div className="crew-task-preview-frame"><CrewTaskBlockRenderer block={previewBlock} index={index} mode="preview" compact onOpenSop={() => {}} /></div></div>
    </details>
  </div>;
}

function withSopPreview(block, sops) {
  if (block.block_type !== "sop_reference" || !block.sop_version_id) return block;
  const sop = sops.find((item) => item.version_id === block.sop_version_id);
  if (!sop) return block;
  return { ...block, sop_reference: { sop_version_id: sop.version_id, title: sop.title, version: sop.version } };
}

function LegacyRulesEditor({ draft, setDraft, structuredCount }) {
  const evidence = draft.blocks.some((x) => x.evidence_requirement === "note") ? "note" : structuredCount ? "structured" : "none";
  const setEvidence = (value) => { if (value === "structured") return; setDraft({ ...draft, blocks: draft.blocks.map((x) => ({ ...x, evidence_requirement: value })) }); };
  return <div className="space-y-4"><fieldset><legend className="field-label mb-2">Who completes this task?</legend><div className="grid gap-2 md:grid-cols-3">{[["any_assigned", "Any assigned Crew", "The first eligible Crew member may complete it"], ["every_assigned", "Every assigned Crew", "Each assigned person completes their own copy"], ["one_for_team", "One Crew for the team", "One completion closes it for the assigned team"]].map(([value, label, help]) => <button key={value} type="button" aria-pressed={draft.completion_rule === value} className={`rounded-xl border p-3 text-left ${draft.completion_rule === value ? "border-primary bg-emerald-50" : "border-border bg-white"}`} onClick={() => setDraft({ ...draft, completion_rule: value })}><b className="block text-sm">{label}</b><small className="mt-1 block text-text-secondary">{help}</small></button>)}</div></fieldset><fieldset><legend className="field-label mb-2">Completion evidence</legend><div className="grid gap-2 md:grid-cols-3">{[["none", "No additional evidence"], ["note", "Note"], ["structured", "Structured task blocks"]].map(([value, label]) => <button key={value} type="button" disabled={value === "structured" && !structuredCount} aria-pressed={evidence === value} className={`rounded-xl border p-3 text-left text-sm font-semibold disabled:cursor-not-allowed disabled:bg-slate-100 disabled:text-text-muted ${evidence === value ? "border-primary bg-emerald-50" : "border-border bg-white"}`} onClick={() => setEvidence(value)}>{label}</button>)}</div>{structuredCount ? <p className="mt-2 text-sm text-emerald-800">Structured evidence is already collected by {structuredCount} task block{structuredCount === 1 ? "" : "s"}.</p> : null}</fieldset><div className="grid gap-2 sm:grid-cols-2"><label className="flex items-center gap-2 rounded-xl bg-white p-3 text-sm"><input type="checkbox" checked={draft.allow_exception} onChange={(event) => setDraft({ ...draft, allow_exception: event.target.checked })} />Allow exception</label>{draft.allow_exception ? <label className="flex items-center gap-2 rounded-xl bg-white p-3 text-sm"><input type="checkbox" checked={draft.exception_requires_reason} onChange={(event) => setDraft({ ...draft, exception_requires_reason: event.target.checked })} />Require exception reason</label> : null}<label className="flex items-center gap-2 rounded-xl bg-white p-3 text-sm"><input type="checkbox" checked={draft.manager_review_required} onChange={(event) => setDraft({ ...draft, manager_review_required: event.target.checked })} />Manager review required</label></div><details className="rounded-xl border border-border bg-white"><summary className="cursor-pointer px-4 py-3 text-sm font-semibold">Advanced settings</summary><div className="border-t border-border p-4"><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={draft.allow_late_completion !== false} onChange={(event) => setDraft({ ...draft, allow_late_completion: event.target.checked })} />Allow late completion</label><p className="mt-2 text-xs text-text-secondary">Photo evidence remains unavailable until secure Operations media storage is configured.</p></div></details></div>;
}

function RulesEditor({ draft, setDraft, structuredCount }) {
  const completion = canonicalCompletionRule(draft.completion_rule);
  const noteRule = additionalNoteRule(draft.blocks);
  const setAdditionalNote = (value) => setDraft({ ...draft, blocks: draft.blocks.map((block) => RESPONSE_BLOCK_TYPES.has(block.block_type) ? { ...block, evidence_requirement: value } : block) });
  return <div className="space-y-4">
    <fieldset><legend className="field-label mb-2">Who completes this task?</legend><div className="grid gap-2 md:grid-cols-2">{[["one_for_team", "One completion for this task", "Any eligible assigned Crew can complete it once for the group."], ["every_assigned", "Each assigned Crew must complete", "Every eligible assigned Crew completes their own requirement."]].map(([value, label, help]) => <button key={value} type="button" aria-pressed={completion === value} className={`rounded-xl border p-3 text-left ${completion === value ? "border-primary bg-emerald-50" : "border-border bg-white"}`} onClick={() => setDraft({ ...draft, completion_rule: value })}><b className="block text-sm">{label}</b><small className="mt-1 block text-text-secondary">{help}</small></button>)}</div></fieldset>
    <fieldset><legend className="field-label mb-2">Evidence from task responses</legend><div className="rounded-xl bg-emerald-50 p-3 text-sm text-emerald-900"><b className="block">{structuredCount ? `✓ Evidence collected from ${structuredCount} task response${structuredCount === 1 ? "" : "s"}` : "No structured responses in this Task"}</b><span className="mt-1 block">Answers from choices, measurements, ratings and confirmations are saved as canonical execution evidence.</span></div><div className="mt-3"><p className="field-label mb-2">Additional completion note</p><div className="grid gap-2 md:grid-cols-3">{[["none", "Not required"], ["optional_note", "Optional"], ["note", "Required"]].map(([value, label]) => <button key={value} type="button" aria-pressed={noteRule === value} className={`rounded-xl border p-3 text-left text-sm font-semibold ${noteRule === value ? "border-primary bg-emerald-50" : "border-border bg-white"}`} onClick={() => setAdditionalNote(value)}>{label}</button>)}</div></div></fieldset>
    <div className="grid gap-2 sm:grid-cols-2"><label className="flex items-center gap-2 rounded-xl bg-white p-3 text-sm"><input type="checkbox" checked={draft.allow_exception} onChange={(event) => setDraft({ ...draft, allow_exception: event.target.checked })} />Allow exception</label>{draft.allow_exception ? <label className="flex items-center gap-2 rounded-xl bg-white p-3 text-sm"><input type="checkbox" checked={draft.exception_requires_reason} onChange={(event) => setDraft({ ...draft, exception_requires_reason: event.target.checked })} />Require exception reason</label> : null}<label className="flex items-center gap-2 rounded-xl bg-white p-3 text-sm"><input type="checkbox" checked={draft.manager_review_required} onChange={(event) => setDraft({ ...draft, manager_review_required: event.target.checked })} />Manager review required</label></div>
  </div>;
}

function TaskSummary({ draft, outletName, structuredCount }) {
  const required = draft.blocks.filter((block) => block.is_required !== false).length;
  const noteRule = additionalNoteRule(draft.blocks);
  return <aside className="sticky top-0 hidden border-l border-border bg-white p-5 xl:block"><p className="text-sm font-bold text-text-primary">Task summary</p><h3 className="mt-4 text-lg font-bold">{draft.name || "Untitled Task"}</h3><Badge tone={tone(draft.priority)}>{priorityLabel(draft.priority)}</Badge><dl className="mt-5 space-y-4 text-sm"><div><dt className="text-text-muted">Schedule</dt><dd className="font-semibold">{scheduleLabel(draft)}</dd></div><div><dt className="text-text-muted">Assignment result</dt><dd className="font-semibold">{assignmentSummary(draft, outletName)}</dd><small className="text-text-secondary">{draft.on_duty_only ? "Latest published roster · Working shifts only" : "Eligible Crew in this outlet"}</small></div><div><dt className="text-text-muted">Content</dt><dd className="font-semibold">{draft.blocks.length} blocks · {required} required</dd><small className="text-text-secondary">{structuredCount} structured response field{structuredCount === 1 ? "" : "s"} · additional note {noteRule === "none" ? "not required" : noteRule}</small></div><div><dt className="text-text-muted">Completion</dt><dd className="font-semibold">{completionRuleLabel(draft.completion_rule)}</dd></div></dl></aside>;
}

function LegacyTaskSummary({ draft, outletName, structuredCount }) { const required = draft.blocks.filter((block) => block.is_required !== false).length; return <aside className="sticky top-0 hidden border-l border-border bg-white p-5 xl:block"><p className="text-sm font-bold text-text-primary">Task summary</p><h3 className="mt-4 text-lg font-bold">{draft.name || "Untitled Task"}</h3><Badge tone={tone(draft.priority)}>{priorityLabel(draft.priority)}</Badge><dl className="mt-5 space-y-4 text-sm"><div><dt className="text-text-muted">Schedule</dt><dd className="font-semibold">{scheduleLabel(draft)}</dd>{draft.start_time || draft.due_time ? <small className="text-text-secondary">{draft.start_time || "Start of day"} – {draft.due_time || "End of day"}</small> : null}</div><div><dt className="text-text-muted">Assignment</dt><dd className="font-semibold">{assignmentSummary(draft, outletName)}</dd></div><div><dt className="text-text-muted">Content</dt><dd className="font-semibold">{draft.blocks.length} blocks · {required} required</dd>{structuredCount ? <small className="text-text-secondary">{structuredCount} structured response fields</small> : null}</div><div><dt className="text-text-muted">Completion</dt><dd className="font-semibold">{{ any_assigned: "Any assigned Crew", every_assigned: "Every assigned Crew", one_for_team: "One Crew for the team" }[draft.completion_rule]}</dd></div></dl></aside>; }

function assignmentSummary(draft, outletName) { const base = draft.assignment_type === "position" ? draft.applicable_positions.join(", ") || "Selected positions" : draft.assignment_type === "specific_crew" ? `${draft.applicable_employee_ids.length} selected Crew` : draft.assignment_type === "group" ? draft.applicable_group_names.join(", ") || "Selected groups" : "All Crew"; return `${draft.on_duty_only ? "Scheduled " : ""}${base} at ${outletName}`; }
function TaskActionMenu({ row, position, onManage, onDuplicate, onArchive }) {
  return <div role="menu" className="fixed z-[90] w-48 rounded-xl border border-border bg-white p-1.5 text-left shadow-card" style={{ top: position.top, right: position.right }}>
    {["active", "paused"].includes(row.status) ? <button className="w-full rounded-lg px-3 py-2 text-left text-sm font-medium hover:bg-slate-50" onClick={onManage}>Manage Schedule</button> : null}
    <button className="w-full rounded-lg px-3 py-2 text-left text-sm font-medium hover:bg-slate-50" onClick={onDuplicate}>Duplicate</button>
    {row.status === "ended" ? <button className="w-full rounded-lg px-3 py-2 text-left text-sm font-medium text-rose-700 hover:bg-rose-50" onClick={onArchive}>Archive</button> : null}
  </div>;
}

function ManageSchedule({ task, onClose, onAction }) {
  const [endDate, setEndDate] = useState(task.schedule_end_date || "");
  return <Modal title="Manage Schedule" description={`${task.name} · ${statusLabel(task.status)}`} size="md" onClose={onClose} footer={<button className="btn-secondary" onClick={onClose}>Close</button>}>
    <div className="space-y-5">
      <section className="grid gap-3 rounded-xl bg-slate-50 p-4 sm:grid-cols-2"><SummaryItem label="Schedule" value={scheduleLabel(task)} /><SummaryItem label="Next Run" value={<TaskDateTime value={task.next_run} />} /></section>
      {task.schedule_type !== "one_time" && ["active", "paused"].includes(task.status) ? <section><label className="field-label">End Date <span className="font-normal text-text-muted">(optional)</span><input className="control mt-1 w-full" type="date" min={localDate()} value={endDate} onChange={(event) => setEndDate(event.target.value)} /></label><div className="mt-3 flex justify-end"><button className="btn-secondary" onClick={() => onAction("set_end_date", endDate || null)}><CalendarClock size={15} /> Save End Date</button></div></section> : null}
      <section className="space-y-2 border-t border-border pt-4">
        {task.status === "active" ? <button className="btn-secondary w-full justify-start" onClick={() => onAction("pause")}><Pause size={16} /> Pause future instance generation</button> : null}
        {task.status === "paused" ? <button className="btn-secondary w-full justify-start" onClick={() => onAction("resume")}><Play size={16} /> Resume schedule</button> : null}
        {["active", "paused"].includes(task.status) ? <button className="btn-secondary w-full justify-start text-rose-700" onClick={() => onAction("end")}><Square size={16} /> End Schedule permanently</button> : null}
      </section>
      <p className="text-xs text-text-secondary">Pause, resume, end date and archive never rewrite frozen instances or historical execution evidence.</p>
    </div>
  </Modal>;
}

function TaskDetail({ task, canManage, onEditDraft, onClose }) {
  const [detail, setDetail] = useState(null); const [result, setResult] = useState(null); const [loading, setLoading] = useState(true); const [tab, setTab] = useState("overview");
  useEffect(() => { let live = true; setLoading(true); crewService.taskAdminDetail(task.id).then((value) => { if (live) setDetail(value); }).catch(() => { if (live) setDetail({ definition: task, progress: {}, history: [] }); }).finally(() => { if (live) setLoading(false); }); return () => { live = false; }; }, [task]);
  async function viewResult(instanceId) { setLoading(true); try { setResult(await crewService.taskAdminResult(instanceId)); } finally { setLoading(false); } }
  const definition = detail?.definition || task;
  const draft = detail?.draft;
  return <Modal title={result ? `Execution Result · ${definition.name}` : definition.name} description={result ? `${formatDate(result.instance?.business_date)} · frozen v${result.instance?.template_revision}` : `${TASK_TYPES.find((x) => x.value === definition.task_type)?.label || "Task"} · Current v${definition.revision}${draft && draft.id !== definition.id ? ` · Draft v${draft.revision}` : ""}`} size="xl" panelClassName="max-h-[90vh]" bodyClassName="p-0" onClose={onClose} footer={<><button className="btn-secondary" onClick={result ? () => setResult(null) : onClose}>{result ? <><ArrowLeft size={15} /> Back to Executions</> : "Close"}</button>{!result && canManage ? <button className="btn-primary" onClick={() => onEditDraft({ ...task, has_draft: Boolean(draft), draft_version: draft ? { id: draft.id, revision: draft.revision } : null, current_version: { id: definition.id, revision: definition.revision } })}>{draft ? "Continue Draft" : "New Revision"}</button> : null}</>}>
    {loading ? <div className="p-8 text-sm text-text-muted">Loading Task history…</div> : result ? <TaskExecutionResult result={result} /> : <>
      <div className="border-b border-border px-5 pt-4 md:px-6"><div className="flex flex-wrap gap-2 pb-4"><Badge tone={tone(definition.status)}>{statusLabel(definition.status)}</Badge><Badge tone={tone(definition.priority)}>{priorityLabel(definition.priority)}</Badge>{draft && draft.id !== definition.id ? <Badge tone="warning">Draft v{draft.revision}</Badge> : null}</div><div className="flex gap-1" role="tablist" aria-label="Task detail sections">{[["overview", "Overview"], ["executions", "Executions"], ["versions", "Versions"]].map(([value, label]) => <button key={value} role="tab" aria-selected={tab === value} className={`border-b-2 px-3 py-2 text-sm font-semibold ${tab === value ? "border-primary text-primary" : "border-transparent text-text-secondary"}`} onClick={() => setTab(value)}>{label}</button>)}</div></div>
      <div className="space-y-6 p-5 md:p-6">
        {tab === "overview" ? <TaskOverview definition={definition} task={task} progress={detail?.progress} /> : null}
        {tab === "executions" ? <TaskExecutions history={detail?.history || []} onViewResult={viewResult} /> : null}
        {tab === "versions" ? <TaskVersions versions={detail?.versions || []} currentId={definition.id} draftId={draft?.id} /> : null}
      </div>
    </>}
  </Modal>;
}

function TaskExecutionResult({ result }) {
  const [view, setView] = useState("item");
  const crew = result.assignees || [];
  const summary = crew.reduce((value, person) => ({ ...value, [person.status]: (value[person.status] || 0) + 1 }), {});
  return <div className="space-y-5 p-5 md:p-6"><div className="grid grid-cols-2 gap-2 sm:grid-cols-4">{[["Completed", summary.completed || summary.completed_with_exceptions || 0], ["In Progress", summary.in_progress || 0], ["Not Started", summary.not_started || 0], ["Exceptions", summary.completed_with_exceptions || 0]].map(([label, value]) => <article key={label} className="rounded-xl bg-slate-50 p-3"><small className="text-text-muted">{label}</small><strong className="mt-1 block text-xl">{value}</strong></article>)}</div><div className="flex flex-wrap items-center justify-between gap-3"><Badge tone={tone(result.status)}>{statusLabel(result.status)}</Badge><div className="inline-flex rounded-lg bg-slate-100 p-1" role="tablist" aria-label="Execution result view"><button role="tab" aria-selected={view === "item"} className={`rounded-md px-3 py-1.5 text-sm font-semibold ${view === "item" ? "bg-white text-primary shadow-sm" : "text-text-secondary"}`} onClick={() => setView("item")}>By Task Item</button><button role="tab" aria-selected={view === "crew"} className={`rounded-md px-3 py-1.5 text-sm font-semibold ${view === "crew" ? "bg-white text-primary shadow-sm" : "text-text-secondary"}`} onClick={() => setView("crew")}>By Crew</button></div></div>{view === "item" ? <TaskResultByItem blocks={result.blocks || []} /> : <TaskResultByCrew crew={crew} blocks={result.blocks || []} />}</div>;
}

function TaskOverview({ definition, task, progress }) {
  const blocks = definition.blocks?.length ? definition.blocks : task.blocks || [];
  return <>
    <section><h3 className="mb-3 font-bold">Task Setup</h3><div className="grid gap-x-5 gap-y-4 rounded-xl bg-slate-50 p-4 sm:grid-cols-2 lg:grid-cols-3"><SummaryItem label="Schedule" value={scheduleLabel(definition)} /><SummaryItem label="Assignment" value={assignmentLabel(definition)} /><SummaryItem label="Completion Rule" value={completionRuleLabel(definition.completion_rule)} /><SummaryItem label="Priority" value={priorityLabel(definition.priority)} /><SummaryItem label="Created Date" value={formatNumericDate(definition.created_date)} /><SummaryItem label="Next Run" value={<TaskDateTime value={definition.next_run} />} /><SummaryItem label="Version" value={<TaskVersionCell row={{ ...definition, has_draft: task.has_draft, draft_version: task.draft_version, current_version: task.current_version || definition.current_version }} />} /></div></section>
    <section><h3 className="mb-3 font-bold">Execution Progress</h3><div className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-6">{[["Instances", "instances"], ["Completed", "completed"], ["In Progress", "in_progress"], ["Not Started", "not_started"], ["Exceptions", "exception"], ["Overdue", "overdue"]].map(([label, key]) => <article key={key} className="rounded-xl border border-border p-3"><small className="block text-text-muted">{label}</small><strong className="mt-1 block text-xl">{progress?.[key] || 0}</strong></article>)}</div></section>
    <TaskContentOverview blocks={blocks} />
  </>;
}

function TaskContentOverview({ blocks }) {
  return <section><div className="mb-3 flex items-end justify-between gap-3"><div><h3 className="font-bold">Task Content</h3><p className="mt-1 text-sm text-text-secondary">Read-only preview of the current Task version.</p></div><span className="text-xs font-semibold text-text-muted">{blocks.length} block{blocks.length === 1 ? "" : "s"}</span></div>{blocks.length ? <div className="overflow-hidden rounded-xl border border-border">{blocks.map((block, index) => <article key={block.id || index} className="grid gap-2 border-b border-border px-4 py-3 last:border-0 sm:grid-cols-[2rem_minmax(0,1fr)_auto]"><b className="text-sm text-primary">{String(index + 1).padStart(2, "0")}</b><div className="min-w-0"><strong className="block text-sm text-text-primary">{block.title || "Untitled block"}</strong>{block.description ? <p className="mt-1 text-sm text-text-secondary">{block.description}</p> : null}<div className="mt-1.5 flex flex-wrap gap-x-3 gap-y-1 text-xs text-text-muted">{block.is_required !== false ? <span>Required</span> : <span>Optional</span>}{block.evidence_requirement && block.evidence_requirement !== "none" ? <span>{evidenceLabel(block.evidence_requirement)}</span> : null}{block.sop_reference?.version ? <span>Pinned SOP v{block.sop_reference.version}</span> : null}</div></div><span className="justify-self-start sm:justify-self-end"><Badge tone="neutral">{blockTypeLabel(block.block_type)}</Badge></span></article>)}</div> : <div className="rounded-xl border border-dashed border-border p-6 text-center text-sm text-text-secondary">No Task content in this version.</div>}</section>;
}
function TaskExecutions({ history, onViewResult }) { return <section><h3 className="mb-3 font-bold">Execution History</h3>{history.length ? <div className="overflow-hidden rounded-xl border border-border">{history.map((row) => <div key={row.instance_id} className="grid items-center gap-3 border-b border-border px-4 py-3 last:border-0 sm:grid-cols-[120px_150px_minmax(0,1fr)_auto]"><strong className="text-sm">{formatDate(row.date)}</strong><span><Badge tone={tone(row.status)}>{statusLabel(row.status)}</Badge><small className="ml-2 text-text-muted">v{row.revision}</small></span><span className="text-sm text-text-secondary">{row.actors?.length ? row.actors.map((actor) => actor.name).join(", ") : "No activity yet"}{row.completed_at ? ` · ${formatTime(row.completed_at)}` : ""}</span>{row.has_result ? <button className="btn-secondary px-3 py-1.5 text-xs" onClick={() => onViewResult(row.instance_id)}>View Result</button> : <span className="text-right text-xs text-text-muted">No result</span>}</div>)}</div> : <div className="rounded-xl border border-dashed border-border p-6 text-center text-sm text-text-secondary">No instances have been generated yet.</div>}</section>; }
function TaskVersions({ versions, currentId, draftId }) { return <section><div className="mb-3"><h3 className="font-bold">Version History</h3><p className="mt-1 text-sm text-text-secondary">Published revisions and frozen executions remain unchanged when a newer Draft is edited.</p></div><div className="overflow-hidden rounded-xl border border-border">{versions.map((version) => <div key={version.id} className="flex items-center justify-between gap-4 border-b border-border px-4 py-3 last:border-0"><div><strong>v{version.revision}</strong><small className="ml-2 text-text-secondary">{formatDate(version.updated_at)}</small><p className="mt-1 text-xs text-text-muted">{version.block_count} blocks · {version.instance_count} frozen instances</p></div><div className="flex gap-2"><Badge tone={tone(version.status)}>{statusLabel(version.status)}</Badge>{version.id === currentId ? <Badge tone="success">Current</Badge> : null}{version.id === draftId ? <Badge tone="warning">Editable Draft</Badge> : null}</div></div>)}</div></section>; }
function TaskResultByItem({ blocks }) { return <section className="space-y-3">{blocks.map((block, index) => { const completed = (block.responses || []).filter((response) => ["completed", "good"].includes(response.status)).length; const exceptions = (block.responses || []).filter((response) => ["exception", "needs_attention"].includes(response.status)).length; return <article key={block.id} className="rounded-xl border border-border p-4"><TaskResultBlockHeader block={block} index={index} /><p className="mt-2 text-xs font-medium text-text-muted">{completed} completed · {exceptions} exceptions · {(block.responses || []).length} responses</p>{block.responses?.length ? <div className="mt-3 space-y-2 border-t border-border pt-3">{block.responses.map((response) => <TaskResponse key={`${block.id}:${response.employee_id}`} response={response} />)}</div> : <p className="mt-3 border-t border-border pt-3 text-sm text-text-muted">No response recorded.</p>}</article>; })}</section>; }
function TaskResultByCrew({ crew, blocks }) { return <section className="space-y-3">{crew.map((person) => { const responses = blocks.flatMap((block, index) => (block.responses || []).filter((response) => response.employee_id === person.employee_id).map((response) => ({ block, index, response }))); return <article key={person.employee_id} className="rounded-xl border border-border p-4"><div className="flex items-center justify-between gap-3"><div><strong>{person.employee_name}</strong><p className="mt-1 text-xs text-text-muted">{responses.length} / {blocks.length} items recorded</p></div><Badge tone={tone(person.status)}>{statusLabel(person.status)}</Badge></div>{responses.length ? <div className="mt-3 space-y-3 border-t border-border pt-3">{responses.map(({ block, index, response }) => <div key={`${block.id}:${person.employee_id}`}><TaskResultBlockHeader block={block} index={index} /><TaskResponse response={response} compact /></div>)}</div> : <p className="mt-3 border-t border-border pt-3 text-sm text-text-muted">No responses recorded.</p>}</article>; })}</section>; }
function TaskResultBlockHeader({ block, index }) { return <div className="flex gap-3"><b className="text-primary">{String(index + 1).padStart(2, "0")}</b><div className="min-w-0 flex-1"><strong>{block.title}</strong>{block.description ? <p className="mt-1 text-sm text-text-secondary">{block.description}</p> : null}<small className="mt-1 block text-text-muted">{BLOCK_TYPES.find((item) => item.value === block.block_type)?.label || block.block_type}{block.sop_reference ? ` · SOP v${block.sop_reference.version}` : ""}</small></div></div>; }
function TaskResponse({ response, compact = false }) { return <div className={`${compact ? "mt-2" : "rounded-lg bg-slate-50 p-3"} text-sm`}><div className="flex items-center justify-between gap-3">{compact ? null : <b>{response.employee_name}</b>}<Badge tone={tone(response.status)}>{statusLabel(response.status)}</Badge></div><p className="mt-1 text-text-secondary">{responseValue(response.response)}</p>{response.note ? <p className="mt-1">Note: {response.note}</p> : null}{response.exception_reason ? <p className="mt-1 text-rose-700">Exception: {response.exception_reason.replaceAll("_", " ")}</p> : null}<small className="mt-1 block text-text-muted">{formatTime(response.completed_at)}</small></div>; }

function SummaryItem({ label, value }) { return <div><p className="text-xs font-medium text-text-muted">{label}</p><p className="mt-1 text-sm font-semibold text-text-primary">{value || "—"}</p></div>; }
function Metric({ icon: Icon, label, value, warning }) { return <article className="card flex items-center gap-3 p-4"><span className={`grid h-9 w-9 place-items-center rounded-xl ${warning ? "bg-rose-50 text-rose-600" : "bg-emerald-50 text-primary"}`}><Icon size={18} /></span><span><small className="block text-text-muted">{label}</small><strong className="text-xl">{value}</strong></span></article>; }
function TaskVersionCell({ row }) {
  const currentRevision = row.current_version?.revision || row.revision;
  const draftRevision = row.draft_version?.revision;
  return <span className="flex flex-col leading-tight"><strong className="text-[13px] font-semibold text-text-primary">v{currentRevision || 1}</strong>{row.has_draft || row.status === "draft" ? <small className="mt-1 text-[11px] font-semibold text-amber-700">{draftRevision && draftRevision !== currentRevision ? `Draft v${draftRevision}` : "Draft changes"}</small> : null}</span>;
}
function TaskDateTime({ value }) {
  if (!value) return <span className="text-sm text-text-muted">—</span>;
  if (value.state !== "scheduled") return <span className="text-[13px] font-semibold text-text-secondary">{statusLabel(value.state)}</span>;
  return <span className="flex flex-col leading-tight"><strong className="text-[13px] font-semibold text-text-primary">{formatNumericDate(value.date)}</strong>{value.at ? <small className="mt-1 text-[11px] text-text-muted">{formatTime(value.at)}</small> : null}</span>;
}
function scheduleLabel(row) {
  if (row.schedule_type === "one_time") return `One-time · ${formatNumericDate(row.effective_date)}`;
  if (row.schedule_type === "shift_based") return ({ before_shift: "Before shift", start_of_shift: "Shift start", during_shift: "During shift", end_of_shift: "Shift end" }[row.schedule_config?.shift_phase || "during_shift"]);
  const frequency = row.schedule_config?.frequency || "every_day";
  if (frequency === "every_day") return "Daily";
  if (frequency === "specific_weekdays") return (row.schedule_config?.weekdays || []).map((day) => ["", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"][day]).filter(Boolean).join(", ") || "Selected weekdays";
  if (frequency === "weekly") return `Weekly · ${["", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"][row.schedule_config?.weekday || 1]}`;
  if (frequency === "monthly") return `Monthly · day ${row.schedule_config?.day || 1}`;
  return `Every ${row.schedule_config?.interval_days || 1} days`;
}
function assignmentLabel(row) { if (row.assignment_type === "position") return row.applicable_positions?.join(", ") || "Position"; if (row.assignment_type === "specific_crew") return `${row.applicable_employee_ids?.length || 0} Crew`; if (row.assignment_type === "group") return row.applicable_group_names?.join(", ") || "Group"; return row.on_duty_only ? "On-duty Crew" : "All Crew"; }
function priorityLabel(value) { return ({ normal: "Normal", important: "Important", critical: "Critical" }[value] || value); }
function blockTypeLabel(value) { return BLOCK_TYPES.find((item) => item.value === value)?.label?.replace(" · Secure media required", "") || String(value || "Block").replaceAll("_", " "); }
function evidenceLabel(value) { return ({ note: "Note evidence", photo: "Photo evidence", number: "Number evidence", confirmation: "Confirmation evidence", structured: "Structured response" }[value] || `${String(value).replaceAll("_", " ")} evidence`); }
function toEditor(row) { return { ...row, schedule_end_date: row.schedule_end_date || "", blocks: (row.blocks || []).map((block) => { const config = { ...(block.config || block.block_config || {}) }; return { ...block, config: { ...config, localization_key: config.localization_key || block.id || crypto.randomUUID() }, sop_version_id: block.sop_version_id || block.sop_reference?.sop_version_id || "" }; }) }; }
function completionRuleLabel(value) { return ({ any_assigned: "Any assigned Crew", every_assigned: "Every assigned Crew", one_for_team: "One Crew for the team" }[value] || value); }
function formatDate(value) { if (!value) return "—"; return new Intl.DateTimeFormat("en-MY", { day: "2-digit", month: "short", year: "numeric", timeZone: "Asia/Kuala_Lumpur" }).format(new Date(`${String(value).slice(0, 10)}T12:00:00+08:00`)); }
function formatNumericDate(value) { if (!value) return "—"; return new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "2-digit", year: "numeric", timeZone: "Asia/Kuala_Lumpur" }).format(new Date(`${String(value).slice(0, 10)}T12:00:00+08:00`)); }
function formatTime(value) { if (!value) return "—"; return new Intl.DateTimeFormat("en-MY", { hour: "numeric", minute: "2-digit", timeZone: "Asia/Kuala_Lumpur" }).format(new Date(value)); }
function responseValue(value) { if (!value || !Object.keys(value).length) return "Completed"; if (Array.isArray(value)) return value.join(", "); if (value.value !== undefined) return `${value.value}${value.unit ? ` ${value.unit}` : ""}`; return Object.entries(value).map(([key, item]) => `${key.replaceAll("_", " ")}: ${Array.isArray(item) ? item.join(", ") : item}`).join(" · "); }
